def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        base = 18.0 if hp > 3 else 40.0
        return max(0.0, min(budget, base))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for oid, opp in alive:
        if float(opp.get('budget', 0)) >= budget:
            rich_opp += 1
        if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 0)) <= 3:
            urgent_opp += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = DAILY_SALARY * 0.7
        avg_prev = DAILY_SALARY * 0.55

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    urgency = 0.0
    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days == 1:
        urgency += 0.55
    if hp <= 2:
        urgency += 0.8
    elif hp <= 4:
        urgency += 0.35

    pressure = 0.45 * scarcity
    pressure += 0.2 if urgent_opp >= 2 else (0.1 if urgent_opp == 1 else 0.0)
    pressure += 0.15 if highest_prev >= 120 else (0.08 if highest_prev >= 80 else 0.0)
    pressure += 0.08 if rich_opp >= 2 else 0.0

    safe_conserve = DAILY_SALARY * (0.28 + 0.18 * scarcity)
    contest = max(avg_prev + 2.0, highest_prev * 0.78)
    emergency = max(highest_prev + 3.0, DAILY_SALARY * 1.05)

    if urgency >= 1.2:
        bid = emergency
    elif urgency >= 0.55:
        bid = max(contest, DAILY_SALARY * (0.72 + 0.18 * scarcity))
    else:
        if pressure >= 0.62:
            bid = max(contest, DAILY_SALARY * (0.58 + 0.16 * scarcity))
        else:
            bid = safe_conserve

    days_left = max(0, 10 - day)
    reserve_floor = 0.0
    if days_left > 0:
        reserve_floor = min(budget * 0.45, days_left * DAILY_SALARY * 0.22)

    max_affordable_today = max(0.0, budget - reserve_floor)
    if urgency >= 1.2:
        max_affordable_today = budget
    elif urgency >= 0.55:
        max_affordable_today = max(max_affordable_today, budget * 0.55)

    bid = min(bid, max_affordable_today)

    if budget < DAILY_SALARY * 0.8 and urgency < 0.55:
        bid = min(bid, budget * 0.45)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opps.append((oid, o))
        except Exception:
            continue

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Yesterday trace reaction
    prev_bids = []
    prev_hp_after = []
    for _, o in alive_opps:
        pt = o.get('previous_trace', {}) or {}
        b = pt.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
                prev_hp_after.append(int(pt.get('hp_after', 0)))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / float(len(prev_bids)) if prev_bids else 0.0

    # Supply pressure: fewer total units -> more value per unit -> bid higher
    # Normalize supply into [0,1]
    if MAX_SUPPLY > MIN_SUPPLY:
        s_norm = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    else:
        s_norm = 0.5
    s_norm = max(0.0, min(1.0, s_norm))

    # Base bid target
    # If someone previously bid near/above salary, we must contest more.
    pressure = 0.0
    if highest_prev_bid > 0:
        pressure = min(1.0, highest_prev_bid / (DAILY_SALARY * 1.25))

    # If my HP is low, avoid overbidding; if HP is high, contest more.
    hp_factor = 0.6
    if my_hp >= 8:
        hp_factor = 1.0
    elif my_hp >= 5:
        hp_factor = 0.85
    elif my_hp >= 3:
        hp_factor = 0.7
    else:
        hp_factor = 0.45

    # If I have no_water_days high, I need water sooner -> bid up.
    urgency = 0.0
    if my_no_water_days >= 3:
        urgency = 1.0
    elif my_no_water_days == 2:
        urgency = 0.7
    elif my_no_water_days == 1:
        urgency = 0.4
    else:
        urgency = 0.2

    # Construct bid cap and target
    # Aim slightly above average, but below highest_prev_bid unless pressure is extreme.
    target = avg_prev_bid * (0.85 + 0.35 * s_norm) + (highest_prev_bid - avg_prev_bid) * (0.25 + 0.35 * pressure)

    # If pressure very high, try to just beat the leader from yesterday.
    if highest_prev_bid >= DAILY_SALARY * 1.8:
        target = highest_prev_bid + 5.0

    # Scale by hp and urgency
    target = target * hp_factor * (0.75 + 0.35 * urgency)

    # Keep within sensible bounds relative to salary and budget
    # Lower bound: ensure some chance to win when supply is high.
    min_bid = DAILY_SALARY * (0.35 + 0.35 * s_norm)
    # Upper bound: don't exceed budget and avoid reckless spending.
    max_bid = min(my_budget, DAILY_SALARY * (1.25 + 0.6 * s_norm) )

    bid = max(min_bid * (0.75 if my_hp <= 2 else 1.0), target)
    bid = min(bid, max_bid)

    # If budget is tiny, just spend what we can.
    if my_budget <= 5.0:
        return max(0.0, my_budget)

    # Final safety clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.2)

    max_prev = max(yesterday_bids) if yesterday_bids else 80

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev * 1.1 + 5)

    if day_context['supply'] < 18:
        return min(my_status['budget'], max_prev * 1.05)

    return min(my_status['budget'], max(DAILY_SALARY * 0.6, max_prev * 0.95))
